-- ═══════════════════════════════════════════════════════════════════════════
-- Contabilización automática de ventas — reglas del contador
-- 757 reglas en 140 combinaciones (documento × tarifa × forma de pago × contribuyente)
--
-- Fuente: docs/CONTABILIZACION AUTOMATICA VENTAS GVM.xlsx (Andrés)
--       → docs/contabilizacion-ventas-normalizado.csv
-- NO editar a mano: si llega una versión nueva del Excel, regenerar.
--
-- Cada línea es: tipo_doc|tarifa_iva|forma_pago|tipo_contribuyente|cuentas...
-- ═══════════════════════════════════════════════════════════════════════════

INSERT INTO public.accounting_rules
    (tenant_id, doc_kind, iva_rate, payment_form, taxpayer_code, account_code, nature, concept)
SELECT t.id, g[1], g[2]::numeric, g[3]::public.payment_form, g[4], acct,
       -- La naturaleza no se guarda: se deduce. En la factura las cuentas de
       -- ingreso, IVA y autorretención-pasivo van al crédito y el resto al débito;
       -- en la nota crédito todo va invertido. Verificado contra las 757 filas
       -- del Excel: 0 excepciones.
       CASE WHEN (g[1] = 'FV') = (acct LIKE '4135%' OR acct LIKE '4175%' OR acct LIKE '2408%' OR acct = '23657501')
            THEN 'C' ELSE 'D' END,
       CASE
         WHEN acct = '13050501' THEN 'CARTERA'
         WHEN acct LIKE '4135%' OR acct LIKE '4175%' THEN 'INGRESO'
         WHEN acct LIKE '2408%' THEN 'IVA'
         WHEN acct = '13551501' THEN 'RETEFUENTE'
         WHEN acct = '13551801' THEN 'RETEICA'
         WHEN acct = '13551701' THEN 'RETEIVA'
         WHEN acct = '13551511' THEN 'AUTORRENTA_ANTICIPO'
         WHEN acct = '23657501' THEN 'AUTORRENTA_PASIVO'
       END
FROM public.tenants t
CROSS JOIN LATERAL (
    SELECT string_to_array(raw, '|') AS g
    FROM unnest(ARRAY[
